vec4 flow(ivec2 p) {
  vec4 fi ;// = read(p, iChannel1);

    for (int x=-1; x<=1; ++x) 
    for (int y=-1; y<=1; ++y)  
 {
     if (x==0 && y==0) {
         fi -= read(p, iChannel1) * -cos(dirs[x+1][y+1]);
         continue;
         }
     float a = -cos(abs(dirs[x+1][y+1] - vec2ang(read(p+ivec2(x,y), iChannel0).xz)));
     if (a > 0.) {
         fi += read(p + ivec2(x,y), iChannel1) * a;
          }

    }
  return normalize(fi ) ;
}



